const input = $input.first().json;
const invoice = (input.data || [])[0];

// Nesta primeira versão só temos tracking_code/transportadora/entregue
// (o que o W2 já grava hoje). Isso dá pra montar um status de 4 etapas
// com segurança. Uma linha do tempo mais granular (etiqueta gerada,
// coletado, saiu para entrega) exigiria o W2 também gravar o campo
// 'status' bruto do Melhor Envio — ainda não persistido, hoje ele só é
// usado de passagem pra montar a mensagem de WhatsApp. Ver nota separada.
const ETAPAS = ['Pedido aprovado', 'Etiqueta gerada e em trânsito', 'Entregue'];

if (!invoice) {
  return [{ json: { sucesso: false, erro: 'Pedido não encontrado' } }];
}

let etapaAtual = 0;
if (invoice.custom_tracking_code) etapaAtual = 1;
if (invoice.custom_entregue == 1) etapaAtual = 2;

return [{
  json: {
    sucesso: true,
    codigo: invoice.custom_tracking_code || null,
    transportadora: invoice.custom_transportadora || null,
    etapas: ETAPAS,
    etapaAtual
  }
}];
